ui.css:
.hud-panel{padding:6px 10px;background:linear-gradient(90deg,rgba(5,2,16,.78),rgba(5,2,16,.35));border-left:2px solid #eef3ff;font:400 16px 'Share Tech Mono',monospace;color:#fffdf2;text-shadow:0 0 2px #000,0 1px 3px #000}
.bar{position:relative;width:236px;height:12px;background:rgba(5,2,16,.85);border:1px solid rgba(238,243,255,.8);box-shadow:0 0 0 1px rgba(0,0,0,.6)}
.bar-fill{height:100%;background:linear-gradient(90deg,#3a0f78,#96158a 22%,#e3443a 48%,#fb9d12 72%,#ffe777 92%,#fffdf2)}
.bar::after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 calc(10% - 1px),rgba(5,2,16,.9) calc(10% - 1px) 10%)}
.scale{height:13px;background:rgba(5,2,16,.82);border:1px solid rgba(238,243,255,.75)}
.scale-fill{height:100%;background:linear-gradient(90deg,#1d0b52,#3a0f78 12%,#64108a 24%,#96158a 36%,#c4256a 47%,#e3443a 57%,#f4701a 67%,#fb9d12 77%,#fdc52e 86%,#ffe777 93%,#fffdf2);box-shadow:0 0 12px rgba(244,112,26,.5)}
.readout{position:relative;padding:4px 18px 6px;font:400 36px/1.05 'Share Tech Mono',monospace;letter-spacing:4px;color:#fffdf2;text-shadow:0 0 2px #000,0 0 14px rgba(251,157,18,.55)}
.readout::before,.readout::after{content:'';position:absolute;top:0;bottom:0;width:10px;border:2px solid rgba(238,243,255,.85)}
.readout::before{left:0;border-right:0}.readout::after{right:0;border-left:0}
.card{position:relative;padding:22px 16px 18px;background:linear-gradient(180deg,rgba(29,11,82,.62),rgba(5,2,16,.94) 46%);border:1px solid rgba(238,243,255,.28)}
.card-title{font:600 18px 'Chakra Petch',sans-serif;text-transform:uppercase;letter-spacing:1.5px;color:#fffdf2}
